{
        "@context": "https://schema.org",
        "@type": "FAQPage",
        "mainEntity": [
          {
            "@type": "Question",
            "name": "What is SPF?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Sender Policy Framework: a DNS TXT record listing which mail servers are authorised to send email on behalf of your domain. Receiving servers check the sending server against that list before your message gets anywhere near the inbox."
            }
          },
          {
            "@type": "Question",
            "name": "What is DKIM?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "DomainKeys Identified Mail: a cryptographic signature added to every outgoing message. Your platform signs with a private key, and receiving servers verify it against the public key published in your DNS — proving the message really came from your domain and wasn't altered in transit."
            }
          },
          {
            "@type": "Question",
            "name": "What is DMARC?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Domain-based Message Authentication, Reporting and Conformance: the policy that ties SPF and DKIM together. It tells receiving servers what to do with mail that fails both checks — nothing (p=none), send it to spam (p=quarantine), or refuse it (p=reject) — and where to send reports about who is sending as your domain."
            }
          },
          {
            "@type": "Question",
            "name": "Why do I need all three?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "They solve different problems: SPF authorises servers, DKIM proves message integrity, and DMARC adds enforcement and visibility. Without DMARC, failing the first two carries no consequence for a spoofer. It's also no longer optional at scale: since 2024, Gmail and Yahoo have required bulk senders to authenticate with SPF, DKIM, and DMARC, and Microsoft introduced matching requirements for Outlook in 2025."
            }
          },
          {
            "@type": "Question",
            "name": "What's a DKIM selector, and why can't you always find mine?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "The selector is the name your DKIM key is published under — selector._domainkey.yourdomain.com. There's no public registry of selectors, so any checker can only try common ones. If none of the ten we try resolve, that's inconclusive rather than a failure: check your email platform's authentication settings for the selector it uses."
            }
          },
          {
            "@type": "Question",
            "name": "What is DMARC alignment?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "DMARC doesn't just ask whether SPF or DKIM passed — it asks whether the domain that passed matches the From address your reader actually sees. An SPF pass on your platform's bounce domain does nothing for DMARC if your From address is your own domain."
            }
          },
          {
            "@type": "Question",
            "name": "Does passing all three guarantee inbox placement?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "No. Authentication is the entry ticket, not the ranking — placement still depends on your sending reputation, list quality, engagement, and content. But the reverse is increasingly true: failing authentication does guarantee trouble, from spam-foldering to outright rejection."
            }
          },
          {
            "@type": "Question",
            "name": "Which DMARC policy should I use?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Follow the progression: start at p=none with a rua reporting address and watch the reports; move to p=quarantine once legitimate mail is passing cleanly; finish at p=reject when you're confident. Don't skip the monitoring stage, or you risk quarantining your own mail."
            }
          }
        ]
      }
